function tetherStringAngle(t) {
  if (t < 1.5) { return 0.02 * Math.sin(1.5 * t); }
  var u = t - 1.5;
  return 0.02 * Math.sin(2.25) * Math.exp(-1.8 * u) + 0.15 * Math.exp(-1.05 * u) * Math.sin(8.5 * u);
}
function tetherWaterAngle(t) {
  if (t < 1.5) { return 0.02 * Math.sin(1.5 * t); }
  return 0.02 * Math.sin(2.25) * Math.exp(-2.6 * (t - 1.5));
}

function updateWater(t) {
  var fall = Math.max(0, t - 5.0);
  var wob = t > 1.0 ? 0.05 * Math.exp(-2.0 * (t - 1.0)) : 0;
  var wobT = Math.max(0, t - 1.0);
  var sag = sstep(1.55, 4.5, t);
  var cav = sstep(2.42, 3.05, t) * (1 - sstep(4.05, 4.7, t));
  var cavR = 0.15 + 0.17 * sstep(2.42, 3.4, t);
  var stretch = sstep(3.7, 5.2, t);
  var pinch = 0.13 * sstep(5.3, 6.6, t);
  var shrink = 1 - 0.4 * sstep(5.6, 7.2, t);
  var vs = 1 + 0.35 * sstep(5.0, 6.8, t);
  var arr = waterGeo.attributes.position.array;
  var y0 = -0.25, i, j;
  for (i = 0; i < waterVC; i++) {
    j = i * 3;
    var x = waterBase[j], y = waterBase[j + 1], z = waterBase[j + 2];
    var v = (y + 1.45) / 2.75;
    var r = Math.sqrt(x * x + z * z);
    if (r > 1e-4) {
      var s = 1 + wob * Math.sin(15 * wobT - 4.0 * v);
      s *= 1 + 0.10 * sag * (1 - v) * (1 - v);
      if (pinch > 0) {
        var env = Math.pow(Math.max(0, Math.sin(Math.PI * v)), 0.75);
        s *= 1 + pinch * Math.sin(v * 22 - 5 * fall) * env;   // Plateau-Rayleigh beads
      }
      s *= shrink;
      x *= s; z *= s;
      y -= 0.12 * sag * (1 - v) * (1 - v);   // hydrostatic bottom sag
      y *= vs;                                // vertical elongation while falling
    }
    if (cav > 0.001) {                        // carve the cavitation tunnel
      var dy = y - y0;
      var d = Math.sqrt(dy * dy + z * z);
      if (d < cavR + 0.36 && d > 1e-4) {
        var infl = cav * (1 - sstep(cavR, cavR + 0.36, d));
        var nd = lerp(d, Math.max(d, cavR * 1.04), infl);
        var k = nd / d;
        y = y0 + dy * k; z *= k;
      }
    }
    if (stretch > 0.001) {                    // forward (-X) momentum transfer
      var side = Math.max(0, -x) / 0.93;
      x -= stretch * 0.55 * Math.pow(side, 1.5);
      x *= 1 + 0.10 * stretch;
    }
    arr[j] = x; arr[j + 1] = y; arr[j + 2] = z;
  }
  waterGeo.attributes.position.needsUpdate = true;
  waterGeo.computeVertexNormals();
  waterMesh.position.set(massX(t), massY(t), 0);
  waterMesh.rotation.z = tetherWaterAngle(t);
}

