/* ============================================================
 * Checkpointed fixed-substep integrator (fully deterministic)
 * ============================================================ */

var ckPos = new Array(Math.floor(TOTAL_STEPS / CK_EVERY) + 2);
var ckVel = new Array(Math.floor(TOTAL_STEPS / CK_EVERY) + 2);
var cachedS = -10;

/* Advance (p, v) from substep k to k+1. No randomness — birth states
 * and all per-particle variation were fixed by the seeded PRNG at init. */
function stepState(p, v, k) {
  var t0 = k * DT, t1 = t0 + DT;
  for (var i2 = 0; i2 < N; i2++) {
    var b = birth[i2];
    if (t1 <= b) { continue; }
    var j = i2 * 3;
    if (t0 <= b) {                       // born during this substep: seed state
      p[j] = spawnPos[j]; p[j + 1] = spawnPos[j + 1]; p[j + 2] = spawnPos[j + 2];
      v[j] = spawnVel[j]; v[j + 1] = spawnVel[j + 1]; v[j + 2] = spawnVel[j + 2];
    }
    var dr = 1 - drag[i2] * DT;
    v[j + 1] -= grav[i2] * DT;
    v[j] *= dr; v[j + 1] *= dr; v[j + 2] *= dr;
    p[j] += v[j] * DT; p[j + 1] += v[j + 1] * DT; p[j + 2] += v[j + 2] * DT;
  }
}

function storeCK(k) {
  if (k % CK_EVERY !== 0) { return; }
  var idx = k / CK_EVERY;
  if (!ckPos[idx]) {
    ckPos[idx] = pos.slice();
    ckVel[idx] = vel.slice();
  }
}

ckPos[0] = pos.slice();   // initial resting state (all particles unborn)
ckVel[0] = vel.slice();

function ensureState(s) {
  if (cachedS === s) { return; }
  var k;
  if (cachedS >= 0 && s > cachedS) {
    for (k = cachedS; k < s; k++) { storeCK(k); stepState(pos, vel, k); }
  } else {
    var base = -1, idx;
    for (idx = Math.floor(s / CK_EVERY); idx >= 0; idx--) {
      if (ckPos[idx]) { base = idx * CK_EVERY; break; }
    }
    if (base < 0) { pos.fill(0); vel.fill(0); base = 0; }
    else { pos.set(ckPos[base / CK_EVERY]); vel.set(ckVel[base / CK_EVERY]); }
    for (k = base; k < s; k++) { storeCK(k); stepState(pos, vel, k); }
  }
  cachedS = s;
  storeCK(s);
  bpos.set(pos); bvel.set(vel);       // fractional remainder: state at s+1
  stepState(bpos, bvel, s);
}

function updateParticlesTo(t) {
  var st = clamp(t, 0, DURATION) * SUB;
  var s = Math.floor(st);
  var frac = st - s;
  if (s > TOTAL_STEPS) { s = TOTAL_STEPS; frac = 0; }
  ensureState(s);
  for (var j = 0; j < N3; j++) {
    renderPos[j] = pos[j] + (bpos[j] - pos[j]) * frac;
  }
  sprayObj.geo.attributes.position.needsUpdate = true;
  mistObj.geo.attributes.position.needsUpdate = true;
  sprayMat.uniforms.uTime.value = t;
  mistMat.uniforms.uTime.value = t;
}

/* ============================================================
 * Deterministic frame evaluation — pure function of simTime
 * ============================================================ */

function renderAt(t) {
  t = clamp(t, 0, DURATION);
  updateParticlesTo(t);

  /* bullet */
  var bx = bulletXAt(t);
  bullet.position.set(bx, -0.25, 0);

  /* motion streak */
  var h = 0.006;
  var ta = Math.max(0, t - h), tb2 = Math.min(DURATION, t + h);
  var v = (bulletXAt(tb2) - bulletXAt(ta)) / Math.max(1e-6, tb2 - ta);
  var av = Math.abs(v);
  var so;
  if (t < 1.02) { so = 0.30 * (1 - sstep(0.96, 1.03, t)); }
  else { so = 0.24 * sstep(3.80, 3.98, t) * (1 - sstep(4.6, 5.3, t)); }
  so *= sstep(2.5, 5.5, av);
  var sl = clamp(av * 0.13, 0.08, 1.6);
  streak.scale.set(sl, 1, 1);
  streak.position.set(bx + sl * 0.5 + 0.12, -0.25, 0);
  streak.material.opacity = so;
  streak.visible = so > 0.012 && t < 5.35;

  /* impact / exit flashes */
  var p1 = (t - 1.0) / 0.16;
  flashEntry.visible = p1 > 0 && p1 < 1;
  if (flashEntry.visible) {
    flashEntry.scale.setScalar(0.12 + 0.5 * p1);
    flashEntry.material.opacity = 0.85 * (1 - p1);
    flashEntry.position.set(ENTRY.x + 0.04, ENTRY.y, 0);
  }
  var p2 = (t - 3.8) / 0.2;
  flashExit.visible = p2 > 0 && p2 < 1;
  if (flashExit.visible) {
    flashExit.scale.setScalar(0.10 + 0.45 * p2);
    flashExit.material.opacity = 0.8 * (1 - p2);
    flashExit.position.set(EXIT.x - 0.04, EXIT.y, 0);
  }

  /* cavitation tunnel */
  var ton = sstep(1.16, 1.55, t) * (1 - sstep(4.05, 4.75, t));
  tunnel.visible = ton > 0.012 && bx < 0.9;
  if (tunnel.visible) {
    var x1 = 0.92, x2 = clamp(bx + 0.1, -0.9, 0.92);
    var len = Math.max(0.04, x1 - x2);
    var rad = (0.13 + 0.10 * sstep(2.4, 3.3, t)) * (1 - 0.55 * sstep(4.0, 4.7, t)) * (1 + 0.07 * Math.sin(t * 29));
    tunnel.scale.set(len, rad, rad);
    tunnel.position.set((x1 + x2) / 2, -0.25, 0);
    tunnel.material.uniforms.uOpacity.value = 0.55 * ton;
  }

  /* backward vent sheet */
  var vp = (t - 2.44) / 1.5;
  vent.visible = vp > 0 && vp < 1;
  if (vent.visible) {
    var g = sstep(0, 0.6, vp);
    var vl = 1.2 * g * (1 - 0.25 * sstep(0.65, 1, vp));
    vent.scale.set(vl, 0.17 + 0.36 * vp, 0.17 + 0.36 * vp);
    vent.position.set(ENTRY.x, ENTRY.y, 0);
    vent.material.uniforms.uOpacity.value = 0.5 * Math.pow(Math.sin(Math.PI * Math.min(1, vp)), 1.3);
  }

  /* forward conical plume */
  fcone.visible = t > 3.82 && t < 5.7;
  if (fcone.visible) {
    var fp = sstep(3.82, 5.05, t);
    var fln = 3.4 * fp * (1 + 0.04 * Math.sin(t * 17));
    var fr = 0.05 + 0.6 * sstep(3.82, 5.2, t);
    fcone.scale.set(fln, fr, fr);
    fcone.position.set(EXIT.x, EXIT.y, 0);
    fcone.material.uniforms.uOpacity.value = 0.5 * sstep(3.84, 4.05, t) * (1 - sstep(4.9, 5.6, t));
  }

  /* latex: dent -> tear retraction -> gone */
  var lAlpha = 1 - sstep(1.5, 1.64, t);
  latex.visible = lAlpha > 0.004;
  latexMat.uniforms.uDent.value = sstep(1.0, 1.09, t) * (1 - sstep(1.12, 1.26, t));
  latexMat.uniforms.uTearR.value = 2.35 * Math.pow(sstep(1.06, 1.52, t), 1.4);
  latexMat.uniforms.uAlpha.value = lAlpha;

  /* knot remnant on the tether */
  var ks = sstep(1.22, 1.44, t);
  knot.visible = ks > 0.004;
  if (knot.visible) {
    var jig = 0.12 * Math.exp(-2.2 * Math.max(0, t - 1.5)) * Math.sin(19 * Math.max(0, t - 1.5));
    knot.scale.setScalar(Math.max(0.0001, ks * (1 + jig)));
    knot.rotation.z = 0.2 * Math.exp(-2.2 * Math.max(0, t - 1.5)) * Math.sin(19 * Math.max(0, t - 1.5));
  }
  hanger.rotation.z = tetherStringAngle(t);

  /* water mass */
  updateWater(t);
  var wOp = 0.92 * (1 - sstep(6.3, 7.4, t));
  waterMat.uniforms.uOpacity.value = wOp;
  waterMat.uniforms.uRedMix.value = 1 - sstep(1.7, 3.4, t);
  waterMesh.visible = wOp > 0.004;

  renderer.render(scene, camera);
}

/* ============================================================
 * Resize
 * ============================================================ */

window.addEventListener('resize', function () {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  updatePointScale();
});

/* ============================================================
 * Playback state machine — COUNTDOWN / PLAYING / PAUSED /
 * REFIRE_HOLD / ENDED
 * ============================================================ */

var elCountdown = document.getElementById('countdown');
var btnToggle = document.getElementById('btn-toggle');
var btnRefire = document.getElementById('btn-refire');
var iconPlay = document.getElementById('icon-play');
var iconPause = document.getElementById('icon-pause');
var scrubber = document.getElementById('scrubber');
var pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

var state = 'PRE';          // flips to COUNTDOWN after first resting render
var simTime = 0;
var playbackSpeed = 1.0;
var countdownElapsed = 0;
var holdElapsed = 0;

function showCountdown(txt) {
  elCountdown.style.display = 'block';
  elCountdown.textContent = txt;
}
function hideCountdown() {
  elCountdown.style.display = 'none';
  elCountdown.textContent = '';
}
function uiPlaying() {
  iconPause.style.display = '';
  iconPlay.style.display = 'none';
  btnToggle.setAttribute('aria-label', 'Pause');
}
function uiPaused() {
  iconPause.style.display = 'none';
  iconPlay.style.display = '';
  btnToggle.setAttribute('aria-label', 'Play');
}

btnToggle.addEventListener('click', function () {
  if (state === 'PLAYING') {
    state = 'PAUSED';
    uiPaused();
  } else if (state === 'PAUSED') {
    state = 'PLAYING';
    uiPlaying();
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
    hideCountdown();
    simTime = 0.000;
    scrubber.value = '0';
    state = 'PAUSED';
    uiPaused();
  } else if (state === 'ENDED') {
    simTime = 0.000;
    scrubber.value = '0';
    hideCountdown();
    state = 'PLAYING';
    uiPlaying();
  }
});

btnRefire.addEventListener('click', function () {
  hideCountdown();
  simTime = 0.000;
  scrubber.value = '0';
  holdElapsed = 0;
  state = 'REFIRE_HOLD';
  uiPlaying();
  renderAt(0);
});

scrubber.addEventListener('input', function () {
  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCountdown(); }
  simTime = parseFloat(scrubber.value) || 0;
  state = 'PAUSED';
  uiPaused();
  renderAt(simTime);
});

pills.forEach(function (pill) {
  pill.addEventListener('click', function () {
    playbackSpeed = parseFloat(pill.dataset.speed);
    pills.forEach(function (other) {
      var active = other === pill;
      other.classList.toggle('is-active', active);
      other.setAttribute('aria-checked', active ? 'true' : 'false');
    });
  });
});

/* ============================================================
 * Main loop
 * ============================================================ */

var lastNow = performance.now();
var firstFrame = true;

function loop(now) {
  requestAnimationFrame(loop);
  var dt = (now - lastNow) / 1000;
  lastNow = now;
  if (!isFinite(dt) || dt < 0) { dt = 0; }

  if (firstFrame) {
    firstFrame = false;
    renderAt(0);                       // initial resting scene, simTime = 0
    state = 'COUNTDOWN';
    countdownElapsed = 0;
    showCountdown('3');
    return;
  }

  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;            // wall-clock, unaffected by playbackSpeed
    if (countdownElapsed < 1) { showCountdown('3'); }
    else if (countdownElapsed < 2) { showCountdown('2'); }
    else if (countdownElapsed < 3) { showCountdown('1'); }
    else {
      hideCountdown();
      state = 'PLAYING';
      uiPlaying();
    }
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;                 // wall-clock, unaffected by playbackSpeed
    if (holdElapsed >= 1.0) {
      state = 'PLAYING';
      uiPlaying();
    }
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + Math.min(dt, 0.1) * playbackSpeed);
    scrubber.value = simTime.toFixed(3);
    if (simTime >= DURATION) {
      simTime = DURATION;
      scrubber.value = DURATION.toFixed(3);
      state = 'ENDED';
      uiPaused();
    }
  }

  renderAt(simTime);
}

requestAnimationFrame(loop);

})();
</script>
</body>
</html>
